// ====================== HELPERS ======================
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const MEAL_LABEL={breakfast:"Breakfast",lunch:"Lunch",dinner:"Dinner",snack:"Snack",drink:"Drink"};
const GOAL_LABEL={glucose:"Glucose",iron:"Iron",thyroid:"Thyroid",liver:"Liver"};
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const fmt=n=>Math.round(n).toLocaleString('en-US');
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function noteTarget(){try{if(typeof HABIT!=='undefined'){HABIT.target=TARGET;saveHabit();}}catch(e){}}

// diet auto-tagging (same logic as library, conservative)
const DIET_DEFS=[{key:"vegetarian",label:"Vegetarian"},{key:"vegan",label:"Vegan"},{key:"pescatarian",label:"Pescatarian"},{key:"dairyfree",label:"Dairy-free"},{key:"glutenfree",label:"Gluten-free"},{key:"nutfree",label:"Nut-free"}];
const DIET_LABEL=Object.fromEntries(DIET_DEFS.map(d=>[d.key,d.label]));
function dietTags(r){
  const t=r.ingredients.join(" ; ").toLowerCase();
  const meat=/\b(chicken|turkey|veal|beef|pork|lamb|rabbit|quail|mince|liver|hearts?|jam[o\u00f3]n|prosciutto|bacon|gizzards?)\b/.test(t);
  const fish=/\b(fish|tuna|salmon|cod|hake|tilapia|anchovy|anchovies|herring|mackerel|sardines?|caviar|roe|trout)\b/.test(t);
  const sea=/\b(shrimps?|prawns?|squid|seafood|crab|mussels?|scallops?|octopus|calamari)\b/.test(t);
  const egg=/\beggs?\b/.test(t);
  const d=t.replace(/coconut (milk|cream)/g,"").replace(/soy (milk|cream)/g,"");
  const dairy=/\b(cheese|feta|parmesan|mozzarella|ricotta|burrata|brie|camembert|cheddar|quark|halloumi|brynza|suluguni|gouda|skyr|yogurt|butter|ghee)\b/.test(d)||/\b(cream|milk)\b/.test(d);
  const honey=/\bhoney\b/.test(t);
  const gluten=/\b(bread|pasta|bulgur|lavash|orzo|penne|couscous|barley|wheat|rye|semolina|oats?|oatmeal)\b/.test(t);
  const nut=/\b(almonds?|walnuts?|pistachios?|cashews?|hazelnuts?|pecans?|macadamias?|pine ?nuts?|brazil ?nuts?|nuts?|pesto)\b/.test(t);
  const out=[];
  if(!meat&&!fish&&!sea) out.push("vegetarian");
  if(!meat&&!fish&&!sea&&!egg&&!dairy&&!honey) out.push("vegan");
  if(!meat) out.push("pescatarian");
  if(!dairy) out.push("dairyfree");
  if(!gluten) out.push("glutenfree");
  if(!nut) out.push("nutfree");
  return out;
}
function displayDiet(t){let a=[...t];if(a.includes("vegan"))a=a.filter(x=>x!=="vegetarian"&&x!=="pescatarian");else if(a.includes("vegetarian"))a=a.filter(x=>x!=="pescatarian");return a;}
function slugify(s){return s.toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48);}
(function(){const seen={};RECIPES.forEach((r,i)=>{r.diet=dietTags(r);let s=slugify(r.name);if(seen[s])s=s+'-'+i;seen[s]=1;r.slug=s;});})();

// ====================== PHOTO ======================
function photoHTML(r,klass){
  return `<div class="${klass}">
    <div class="photo-fb"><svg class="i"><use href="#i-bowl"/></svg><span>${esc(rName(r))}</span></div>
    <img loading="lazy" alt="${esc(rName(r))}" src="${(window.MEAL_IMG&&MEAL_IMG[r.slug])||('assets/meals/'+r.slug+'.webp')}" onload="this.classList.add('on')" onerror="this.remove()">
  </div>`;
}

// ====================== NAV ======================
function jumpTo(tab){
  $$('nav button').forEach(x=>x.classList.toggle('on',x.dataset.tab===tab));
  $$('.panel').forEach(p=>p.classList.toggle('on',p.id===tab));
  // hero (brand + coach card) belongs to Today only, so other tabs land straight on their block
  const hero=document.getElementById('hero-block'); if(hero)hero.style.display=(tab==='today')?'':'none';
  // keep active tab visible in the scrolling nav (mobile)
  const navin=$('nav .navin'),act=$('nav button.on');
  if(navin&&act){try{navin.scrollTo({left:act.offsetLeft-navin.clientWidth/2+act.clientWidth/2,behavior:'smooth'});}catch(e){navin.scrollLeft=act.offsetLeft-navin.clientWidth/2+act.clientWidth/2;}}
  // land at the top of the chosen block, navbar stays pinned above it
  window.scrollTo({top:0,behavior:'smooth'});
}
$$('nav button').forEach(b=>b.addEventListener('click',()=>jumpTo(b.dataset.tab)));
$$('[data-jump]').forEach(b=>b.addEventListener('click',()=>jumpTo(b.dataset.jump)));
// navbar reads as a solid bar once it pins to the top
(function(){const navEl=document.querySelector('nav');if(!navEl)return;
  function onScroll(){navEl.classList.toggle('stuck',navEl.getBoundingClientRect().top<=0);}
  window.addEventListener('scroll',onScroll,{passive:true});onScroll();
})();

// Вішаємо кліки ВИКЛЮЧНО на кнопки, які мають атрибут data-tab
$$('nav button[data-tab]').forEach(b=>b.addEventListener('click',()=>jumpTo(b.dataset.tab)));
$$('[data-jump]').forEach(b=>b.addEventListener('click',()=>jumpTo(b.dataset.jump)));

