(function(){const navEl=document.querySelector('nav');if(!navEl)return;
  function onScroll(){navEl.classList.toggle('stuck',navEl.getBoundingClientRect().top<=0);}
  window.addEventListener('scroll',onScroll,{passive:true});onScroll();
})();

// Вішаємо кліки на ВСІ кнопки з data-tab та data-jump
document.querySelectorAll('button[data-tab]').forEach(b => b.addEventListener('click', () => jumpTo(b.dataset.tab)));
document.querySelectorAll('[data-jump]').forEach(b => b.addEventListener('click', () => jumpTo(b.dataset.jump)));

// Логіка самого бургера (відкриття/закриття по кліку на три смужки)
document.addEventListener('DOMContentLoaded', () => {
  const burgerBtn = document.getElementById('znpBurger');
  const mobileDropdown = document.getElementById('znpDropdown');

  if (burgerBtn && mobileDropdown) {
    burgerBtn.addEventListener('click', (e) => {
      e.stopPropagation(); // Щоб клік не спрацьовував на документі
      burgerBtn.classList.toggle('is-active');
      mobileDropdown.classList.toggle('is-open');
      const isExpanded = burgerBtn.getAttribute('aria-expanded') === 'true';
      burgerBtn.setAttribute('aria-expanded', !isExpanded);
    });

    // Закриття меню, якщо клікнули в будь-якому іншому місці екрану
    document.addEventListener('click', (e) => {
      if (!burgerBtn.contains(e.target) && !mobileDropdown.contains(e.target)) {
        burgerBtn.classList.remove('is-active');
        mobileDropdown.classList.remove('is-open');
        burgerBtn.setAttribute('aria-expanded', 'false');
      }
    });
  }
});

// Навбар стає solid при фіксації вгорі
(function(){
  // Якщо у тебе клас .navrow або міняєш на свій обгортковий тег (наприклад, .wrap)
  const navEl = document.querySelector('.navrow') || document.querySelector('nav');
  if(!navEl) return;
  function onScroll(){ navEl.classList.toggle('stuck', navEl.getBoundingClientRect().top <= 0); }
  window.addEventListener('scroll', onScroll, {passive: true}); onScroll();
})();
