function activeFilterCount(){let n=fDiet.size;if(fMeal!=='all')n++;if(fGoal!=='all')n++;if(fSearch)n++;if(fSort!=='featured')n++;
  try{if(+$('#kLo').value>+$('#kLo').min||+$('#kHi').value<+$('#kHi').max)n++;if(+$('#pLo').value>+$('#pLo').min||+$('#pHi').value<+$('#pHi').max)n++;}catch(e){}
  return n;}
function updateFilterCount(){const el=$('#ft-count');if(!el)return;const n=activeFilterCount();el.textContent=n?String(n):'';el.classList.toggle('on',n>0);}
function setupRange(loId,hiId,fillId,valId,min,max,step,unit,loKey,hiKey){
  const lo=$('#'+loId),hi=$('#'+hiId),fill=$('#'+fillId),val=$('#'+valId);
  lo.min=hi.min=min;lo.max=hi.max=max;lo.step=hi.step=step;lo.value=min;hi.value=max;
  function upd(render){
    let a=+lo.value,b=+hi.value;
    if(a>b){if(document.activeElement===lo){a=b;lo.value=a;}else{b=a;hi.value=b;}}
    RNG[loKey]=a;RNG[hiKey]=b;
    const pa=(a-min)/(max-min)*100,pb=(b-min)/(max-min)*100;
    fill.style.left=pa+'%';fill.style.width=(pb-pa)+'%';
    val.textContent=a+'\u2013'+b+(unit?(' '+unit):'');
    lo.style.zIndex=(a>min+(max-min)*0.88)?5:3;
    if(render)renderGrid();
  }
  lo.addEventListener('input',()=>upd(true));
  hi.addEventListener('input',()=>upd(true));
  upd(false);
  resetters.push(()=>{lo.value=min;hi.value=max;upd(false);});
}
setupRange('kLo','kHi','kfill','kval',KMIN,KMAX,10,'kcal','kLo','kHi');
setupRange('pLo','pHi','pfill','pval',PMIN,PMAX,1,'g','pLo','pHi');
