function updateServ(){$('#serv').textContent=servings+' '+(servings===1?t('meals.serving'):t('meals.servings'));renderGrid();}
function macroBars(r){
  if(r.kcal==null) return `<div class="no-macro">${t('meals.drink_nocount')}</div>`;
  const tot=r.p+r.f+r.c||1, kc=Math.round(r.kcal*servings);
  return `<div class="kcal"><b>${kc}</b><span>${t('calc.kcal')} &middot; ${servings>1?('\u00D7'+servings):'1 '+t('meals.serving')}</span></div>
    <div class="bars"><i class="bp" style="width:${r.p/tot*100}%"></i><i class="bf" style="width:${r.f/tot*100}%"></i><i class="bc" style="width:${r.c/tot*100}%"></i></div>
    <div class="legend"><span><i class="bp"></i>P ${Math.round(r.p*servings)}</span><span><i class="bf"></i>F ${Math.round(r.f*servings)}</span><span><i class="bc"></i>C ${Math.round(r.c*servings)}</span></div>`;
}
function rangeUntouched(){return RNG.kLo===KMIN&&RNG.kHi===KMAX&&RNG.pLo===PMIN&&RNG.pHi===PMAX;}
function passesMacro(r){
  if(r.kcal==null) return rangeUntouched();
  return r.kcal>=RNG.kLo&&r.kcal<=RNG.kHi&&r.p>=RNG.pLo&&r.p<=RNG.pHi;
}
function sortList(list){
  if(fSort==='featured') return list;
  const key=fSort.indexOf('kcal')===0?'kcal':'p', dir=fSort.endsWith('asc')?1:-1;
  return list.slice().sort((a,b)=>{
    const av=a[key],bv=b[key];
    if(av==null&&bv==null) return 0;
    if(av==null) return 1; if(bv==null) return -1;
    return (av-bv)*dir;
  });
}
function filtered(){
  const list=RECIPES.filter(r=>
    (fMeal==='all'||r.meal===fMeal)&&
    (fGoal==='all'||r.goals.includes(fGoal))&&
    (fDiet.size===0||[...fDiet].every(d=>r.diet.includes(d)))&&
    passesMacro(r)&&
    (fSearch===''||((rName(r)+' '+r.name).toLowerCase().includes(fSearch)||r.ingredients.join(' ').toLowerCase().includes(fSearch)))
  );
  return sortList(list);
}
