// ====================== MODAL ======================
function trimNum(v){v=Math.round(v*100)/100;return Number.isInteger(v)?String(v):v.toFixed(2).replace(/\.?0+$/,'');}
function scaleAmt(str){
  if(servings===1) return str;
  return str.replace(/(\d+[\u2013-]\d+|\d+[.,]?\d*|\u00BD|\u00BC|\u00BE|\u2153|\u2154)/g,(m)=>{
    const map={'\u00BD':0.5,'\u00BC':0.25,'\u00BE':0.75,'\u2153':0.333,'\u2154':0.667};
    if(map[m]!=null)return trimNum(map[m]*servings);
    if(/[\u2013-]/.test(m)){const[a,b]=m.split(/[\u2013-]/).map(x=>parseFloat(x.replace(',','.')));return trimNum(a*servings)+'\u2013'+trimNum(b*servings);}
    return trimNum(parseFloat(m.replace(',','.'))*servings);
  });
}
function splitIng(s){
  const m=s.match(/^(.*?)(\s)([\d\u00BD\u00BC\u00BE\u2153\u2154][\d\u00BD\u00BC\u00BE\u2153\u2154.,\u2013\- ]*(?:g|ml|tsp|tbsp|kg|l)?.*)$/);
  if(m)return[m[1],scaleAmt(m[3])];
  return[s,''];
}
function openModal(i){
  const r=RECIPES[i];
  const macros = r.kcal==null
    ? `<div class="mm"><b>\u2014</b>${t('mod.drink')}</div>`
    : `<div class="mm"><b>${Math.round(r.kcal*servings)}</b>${t('mod.kcal')}</div><div class="mm"><b>${Math.round(r.p*servings)}</b>${t('mod.protein')}</div><div class="mm"><b>${Math.round(r.f*servings)}</b>${t('mod.fat')}</div><div class="mm"><b>${Math.round(r.c*servings)}</b>${t('mod.carbs')}</div>`;
  $('#modal').innerHTML=`
    ${photoHTML(r,'mphoto')}
    <div class="mhead">
      <button class="close" aria-label="close">\u00D7</button>
      <div class="meal-tag mtag-mono">${MEAL_LABEL[r.meal]} &middot; ${servings>1?servings+' '+t('mod.servings'):t('mod.serving')}</div>
      <h3>${esc(rName(r))}</h3>
      <div class="mmacro">${macros}</div>
      ${r.diet.length?`<div class="mdiet">${displayDiet(r.diet).map(d=>`<span class="dtag">${dietLabel(d)}</span>`).join('')}</div>`:''}
    </div>
    <div class="mbody">
      ${rField(r,"ingredients").length?`<section><h4>${t('mod.ingredients')}</h4><ul class="ing-list">${rField(r,"ingredients").map(ing=>{const[n,a]=splitIng(ing);return`<li><span>${n}</span><span class="amt">${a}</span></li>`}).join('')}</ul></section>`:''}
      ${rField(r,"steps").length?`<section><h4>${t('mod.method')}</h4><ol class="steps">${rField(r,"steps").map(s=>`<li>${s}</li>`).join('')}</ol></section>`:''}
      ${rField(r,"benefits")?`<section><h4>${t('mod.why')}</h4><div class="benefit">${rField(r,"benefits")}</div></section>`:''}
      ${(rField(r,"swaps")||[]).length?`<section><h4>${t('mod.swaps')}</h4><div class="swaps">${rField(r,"swaps").map(s=>`<div class="swap">${s}</div>`).join('')}</div></section>`:''}
      ${r.custom?`<button class="btn btn-ghost del-meal" id="del-meal-btn"><svg class="i" style="width:15px;height:15px"><use href="#i-arrow-right"/></svg> ${t('addm.del')}</button>`:''}
    </div>`;
  $('#overlay').classList.add('on');
  document.body.style.overflow='hidden';
  $('#modal').scrollTop=0;
  const del=$('#del-meal-btn');if(del)del.addEventListener('click',()=>deleteCustom(r.id));
  $('#modal .close').addEventListener('click',closeModal);
}
