const L=LECTURE;
$('#feel-grid').innerHTML=L.feel.map(f=>`<div class="feel-card${f.wide?' wide':''}"><div class="q">${f.q}</div><p>${f.p}</p></div>`).join('');
$('#diet-fail').innerHTML=L.dietFail.map(d=>`<div class="tcard"><h3><span class="ic">${d.ic}</span>${d.t}</h3><p>${d.d}</p></div>`).join('');
(function(){
  const items=L.factors, n=items.length, R=82, C=110, sw=34, gap=0.045;
  const cols=['#8fe85b','#74c94a','#5fae3e','#4f9335','#3f7a2b'];
  const seg=(2*Math.PI)/n;
  let svg=`<svg viewBox="0 0 220 220">`;
  items.forEach((it,i)=>{
    const a0=i*seg+gap, a1=(i+1)*seg-gap;
    const x0=C+R*Math.cos(a0), y0=C+R*Math.sin(a0);
    const x1=C+R*Math.cos(a1), y1=C+R*Math.sin(a1);
    const large=(a1-a0)>Math.PI?1:0;
    svg+=`<path d="M ${x0} ${y0} A ${R} ${R} 0 ${large} 1 ${x1} ${y1}" fill="none" stroke="${cols[i]}" stroke-width="${sw}"/>`;
  });
  svg+=`</svg>`;
  $('#factor-wheel').innerHTML=`<div class="fw-ring">${svg}<div class="fw-center"><b>Weight</b><span>a system of factors</span></div></div><div class="fw-legend">${items.map((it,i)=>`<div class="fw-item"><span class="dot" style="background:${cols[i]}"></span><div><b>${it.ic} ${it.t}</b><p>${it.d}</p></div></div>`).join('')}</div>`;
})();
