async function apiCall(action, payload) {
  try {
    const res = await fetch(API_URL, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify(Object.assign({ action: action, user_id: USER_ID }, payload)),
    });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const json = await res.json();
    if (!json.ok) throw new Error(json.error || 'api error');
    return json.data;
  } catch(e) {
    console.warn('[API] ' + action + ' failed:', e.message);
    return null;
  }
}

async function apiLoadUserData() {
  return apiCall('get_user_data', {});
}
async function apiSaveDay(day, kcal, water) {
  return apiCall('save_day', { day: day, kcal: kcal != null ? kcal : null, water: water || 0 });
}
async function apiSaveSettings(waterGoal, kcalTarget) {
  return apiCall('save_settings', { water_goal: waterGoal, kcal_target: kcalTarget });
}
async function apiSaveMeal(meal) {
  return apiCall('save_meal', { meal: meal });
}
async function apiDeleteMeal(id) {
  return apiCall('delete_meal', { meal_id: id });
}


