// ====================== SCALE HELPER (for shopping-from-plan) ======================
function scaleByMult(str,m){
  if(m===1) return str;
  return str.replace(/(\d+[\u2013-]\d+|\d+[.,]?\d*|\u00BD|\u00BC|\u00BE|\u2153|\u2154)/g,(x)=>{
    const map={'\u00BD':0.5,'\u00BC':0.25,'\u00BE':0.75,'\u2153':0.333,'\u2154':0.667};
    if(map[x]!=null)return trimNum(map[x]*m);
    if(/[\u2013-]/.test(x)){const[a,b]=x.split(/[\u2013-]/).map(v=>parseFloat(v.replace(',','.')));return trimNum(a*m)+'\u2013'+trimNum(b*m);}
    return trimNum(parseFloat(x.replace(',','.'))*m);
  });
}

