// ====================== TODAY / HABIT TRACKER ======================
function localDate(d){d=d||new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
const TODAY_KEY=localDate();

// HABIT живе тільки в пам'яті. Заповнюється виключно з сервера.
let HABIT={days:{},waterGoal:8,target:1600};

// saveHabit — тільки сервер, ніякого localStorage
function saveHabit(key){
  key=key||TODAY_KEY;
  const rec=HABIT.days[key]||{};
  apiSaveDay(key, rec.kcal!=null?rec.kcal:null, rec.water||0);
}

let calMonth=(function(){const d=new Date();d.setDate(1);d.setHours(0,0,0,0);return d;})();
const LOCALE={en:'en-GB',fr:'fr-FR',es:'es-ES',it:'it-IT',pt:'pt-PT',uk:'uk-UA'};
function loc(){return LOCALE[LANG]||'en-GB';}
function getTarget(){return (HABIT.target||TARGET||1600);}
function onTarget(rec){if(!rec||rec.kcal==null)return false;const T=getTarget();return Math.abs(rec.kcal-T)<=Math.max(150,T*0.10);}
function dayState(key){const r=HABIT.days[key];if(!r||r.kcal==null)return 'none';return onTarget(r)?'on':'off';}
function curStreak(){let s=0;const d=new Date();if(!onTarget(HABIT.days[localDate(d)]))d.setDate(d.getDate()-1);for(;;){if(onTarget(HABIT.days[localDate(d)])){s++;d.setDate(d.getDate()-1);}else break;}return s;}
function bestStreak(){const keys=Object.keys(HABIT.days).filter(k=>onTarget(HABIT.days[k])).sort();let best=0,run=0,prev=null;keys.forEach(k=>{if(prev){const diff=Math.round((new Date(k)-new Date(prev))/86400000);run=diff===1?run+1:1;}else run=1;if(run>best)best=run;prev=k;});return best;}
function loggedDays(){return Object.keys(HABIT.days).filter(k=>HABIT.days[k]&&HABIT.days[k].kcal!=null).length;}
function cap(s){return s? s.charAt(0).toUpperCase()+s.slice(1):s;}

function calendarHTML(){
  const y=calMonth.getFullYear(),mo=calMonth.getMonth();
  const monthName=cap(calMonth.toLocaleDateString(loc(),{month:'long',year:'numeric'}));
  let wd='';for(let i=0;i<7;i++){const dd=new Date(2024,0,1+i);wd+=`<span>${cap(dd.toLocaleDateString(loc(),{weekday:'short'})).slice(0,3)}</span>`;}
  const first=new Date(y,mo,1);const lead=(first.getDay()+6)%7;const dim=new Date(y,mo+1,0).getDate();
  const todayK=localDate();
  let cells='';for(let i=0;i<lead;i++)cells+=`<span class="cal-empty"></span>`;
  for(let dn=1;dn<=dim;dn++){
    const key=localDate(new Date(y,mo,dn));const st=dayState(key);const rec=HABIT.days[key];
    const future=key>todayK;const isToday=key===todayK;
    cells+=`<button class="cal-day s-${st}${isToday?' today':''}${future?' future':''}" data-k="${key}" ${future?'disabled':''}>
      <span class="cd-n">${dn}</span>${rec&&rec.kcal!=null?`<span class="cd-k">${fmt(rec.kcal)}</span>`:''}</button>`;
  }
  return `
    <div class="cal-top">
      <div class="cal-streak"><span class="cs-flame"><svg class="i"><use href="#i-flame"/></svg></span><b>${curStreak()}</b> <span class="cs-lab">${curStreak()===1?t('today.streak_one'):t('today.streak')}</span></div>
      <div class="cal-nav"><button class="cal-arrow" data-cal="-1" aria-label="prev">&lsaquo;</button><span class="cal-month">${monthName}</span><button class="cal-arrow" data-cal="1" aria-label="next">&rsaquo;</button></div>
    </div>
    <div class="cal-wd">${wd}</div>
    <div class="cal-grid">${cells}</div>
    <div class="cal-foot">
      <div class="cal-legend"><span class="lg lg-on"></span>${t('cal.legend_on')}<span class="lg lg-off"></span>${t('cal.legend_off')}<span class="lg lg-today"></span>${t('cal.legend_today')}</div>
      <div class="cal-stats"><span>${t('today.best')} <b>${bestStreak()}</b></span><span>${t('today.logged')} <b>${loggedDays()}</b></span></div>
    </div>
    <p class="cal-hint">${t('cal.tap_hint')}</p>`;
}

function openDayEditor(key){
  const rec=HABIT.days[key]||{};const T=getTarget();
  const dl=cap(new Date(key+'T00:00:00').toLocaleDateString(loc(),{weekday:'long',day:'numeric',month:'long'}));
  $('#modal').innerHTML=`
    <div class="day-editor">
      <button class="close" aria-label="close">\u00D7</button>
      <div class="de-date">${dl}</div>
      <h3>${t('cal.log_q')}</h3>
      <div class="de-target">${t('cal.target_lab')}: <b>${fmt(T)}</b> ${t('calc.kcal')}</div>
      <div class="num de-num"><button data-d="-50">&minus;</button><input id="de-kcal" type="number" inputmode="numeric" value="${rec.kcal!=null?rec.kcal:''}" placeholder="0"><button data-d="50">+</button></div>
      <div class="de-status" id="de-status"></div>
      <div class="de-btns"><button class="btn btn-primary" id="de-save">${t('cal.save')}</button>${rec.kcal!=null?`<button class="btn btn-ghost" id="de-clear">${t('cal.clear')}</button>`:''}</div>
    </div>`;
  $('#overlay').classList.add('on');document.body.style.overflow='hidden';$('#modal').scrollTop=0;
  const inp=$('#de-kcal');
  function status(){
    const v=parseInt(inp.value,10);const st=$('#de-status');
    if(!v||isNaN(v)){st.className='de-status';st.textContent='';return;}
    const diff=v-T,band=Math.max(150,T*0.10);
    if(Math.abs(diff)<=band){st.className='de-status on';st.innerHTML=`<svg class="i"><use href="#i-check"/></svg> ${t('cal.on')}`;}
    else{st.className='de-status off';st.textContent=(diff>0?'+':'')+fmt(diff)+' '+t('calc.kcal')+' '+(diff>0?t('cal.over'):t('cal.under'));}
  }
  inp.addEventListener('input',status);status();
  $$('#modal .de-num button').forEach(b=>b.addEventListener('click',()=>{inp.value=Math.max(0,(parseInt(inp.value,10)||0)+ (+b.dataset.d));status();}));
  $('#de-save').addEventListener('click',()=>{const v=Math.max(0,Math.min(8000,parseInt(inp.value,10)||0));const r=HABIT.days[key]||{};r.kcal=v||null;if(r.kcal==null&&!r.water)delete HABIT.days[key];else HABIT.days[key]=r;saveHabit(key);closeModal();renderToday();});
  const dc=$('#de-clear');if(dc)dc.addEventListener('click',()=>{const r=HABIT.days[key];if(r){delete r.kcal;if(!r.water)delete HABIT.days[key];}saveHabit(key);closeModal();renderToday();});
  $('#modal .close').addEventListener('click',closeModal);
}

function renderToday(){
  const host=$('#today-body'); if(!host)return;
  const rec=HABIT.days[TODAY_KEY]||{kcal:null,water:0};
  const goal=HABIT.waterGoal||8;
  const n=Math.max(goal,rec.water||0);
  let glasses='';for(let i=0;i<n;i++)glasses+=`<span class="wg${i<(rec.water||0)?' on':''}"><svg class="i"><use href="#i-droplet"/></svg></span>`;
  host.innerHTML=`
    <div class="cal-card glass">${calendarHTML()}</div>
    <div class="today-grid">
      <div class="t-card t-water glass">
        <div class="tc-head"><h3>${t('today.water')}</h3><span class="tw-count">${rec.water||0} / ${goal} <small>${t('today.of_goal')}</small></span></div>
        <div class="tw-glasses">${glasses}</div>
        <p class="tc-sub">${t('today.water_sub')}</p>
        <div class="tw-ctrl"><button class="btn btn-ghost" id="water-minus" aria-label="${t('today.remove')}">&minus;</button><button class="btn btn-primary" id="water-plus"><svg class="i" style="width:15px;height:15px"><use href="#i-droplet"/></svg> ${t('today.add')}</button></div>
      </div>
      <div class="t-card t-plan glass">
        <div class="tc-head"><h3>${t('plan.title')}</h3></div>
        <p class="tc-sub">${t('plan.sub')}</p>
        <button class="btn btn-primary tp-link" data-jump="plan" style="margin-top:auto"><svg class="i" style="width:15px;height:15px"><use href="#i-bowl"/></svg> ${t('today.to_plan')}</button>
      </div>
    </div>
    <div class="phil glass">
      <div class="phil-eyebrow"><svg class="gx"><use href="#gx-flex"/></svg> ${t('phil.eyebrow')}</div>
      <h3>${t('phil.title')}</h3>
      <p>${t('phil.p1')}</p>
      <p class="phil-strong">${t('phil.p3')}</p>
      <button class="phil-more" data-jump="lecture"><span>${t('phil.read_more')}</span><svg class="i"><use href="#i-arrow-right"/></svg></button>
      <div class="phil-ed">
        <h4>${t('phil.ed_title')}</h4>
        <p>${t('phil.ed_text')}</p>
        <div class="phil-links">
          <a href="https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/" target="_blank" rel="noopener"><svg class="i"><use href="#i-arrow-right"/></svg> ${t('phil.ed_link1')}</a>
          <a href="https://www.beateatingdisorders.org.uk/" target="_blank" rel="noopener"><svg class="i"><use href="#i-arrow-right"/></svg> ${t('phil.ed_link2')}</a>
        </div>
      </div>
    </div>`;
  function putWater(d){const r=HABIT.days[TODAY_KEY]||{kcal:null,water:0};r.water=Math.max(0,Math.min(16,(r.water||0)+d));HABIT.days[TODAY_KEY]=r;saveHabit(TODAY_KEY);renderToday();}
  const wp=$('#water-plus'); if(wp)wp.addEventListener('click',()=>putWater(1));
  const wm=$('#water-minus'); if(wm)wm.addEventListener('click',()=>putWater(-1));
  host.querySelectorAll('.cal-day:not(.future)').forEach(b=>b.addEventListener('click',()=>openDayEditor(b.dataset.k)));
  host.querySelectorAll('[data-cal]').forEach(b=>b.addEventListener('click',()=>{calMonth.setMonth(calMonth.getMonth()+(+b.dataset.cal));renderToday();}));
  host.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>jumpTo(b.dataset.jump)));
}

