function refreshLabels(){
  ['breakfast','lunch','dinner','snack','drink'].forEach(k=>MEAL_LABEL[k]=t('meals.'+k));
  ['glucose','iron','thyroid','liver'].forEach(k=>GOAL_LABEL[k]=t('meals.'+k));
}
function applyI18n(){
  document.querySelectorAll('[data-i18n]').forEach(el=>{const v=t(el.dataset.i18n);if(v)el.textContent=v;});
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{el.setAttribute('placeholder',t(el.dataset.i18nPh));});
  document.documentElement.lang=LANG;
  const tt=$('#theme-toggle'); if(tt)tt.setAttribute('aria-label',document.documentElement.getAttribute('data-theme')==='light'?t('theme.toDark'):t('theme.toLight'));
}
function reRenderDynamic(){
  refreshLabels();
  buildMealChips();buildGoalChips();buildDietChips();buildGenDietChips();
  renderProtoTabs();renderProtoBody();
  renderCycRail();renderCycDetail();
  renderGrid();
  renderPlan();
  renderToday();
  renderSources();
}
function setLang(l){
  LANG=I18N[l]?l:'en';
  try{localStorage.setItem('sbf-lang',LANG);}catch(e){}
  applyI18n();reRenderDynamic();
  const sel=$('#lang-select'); if(sel)sel.value=LANG;
}
(function(){
  const sel=$('#lang-select');
  if(sel){sel.innerHTML=LANGS.map(function(p){return '<option value="'+p[0]+'">'+p[1]+'</option>';}).join('');sel.addEventListener('change',function(e){setLang(e.target.value);});}
  let stored; try{stored=localStorage.getItem('sbf-lang');}catch(e){}
  setLang(I18N[stored]?stored:'en');
})();

// ====================== CUSTOM MEALS ======================
// CUSTOM живе тільки в пам'яті. Заповнюється виключно з сервера.
let CUSTOM=[];
function reindex(){RECIPES.forEach((r,i)=>r.idx0=i);}
function makeRecipe(c){
  const r={name:c.name,meal:c.meal,goals:c.goals||[],kcal:c.kcal,p:c.p||0,f:c.f||0,c:c.c||0,
    ingredients:c.ingredients||[],steps:c.steps||[],benefits:c.benefits||'',swaps:c.swaps||[],custom:true,id:c.id};
  r.diet=dietTags(r);r.slug=c.slug||('custom-'+c.id);return r;
}
function mountCustom(){CUSTOM.forEach(c=>RECIPES.push(makeRecipe(c)));reindex();}

const MEAL_KEYS=['breakfast','lunch','dinner','snack','drink'];
function openAddMeal(){
  $('#modal').innerHTML=`
    <div class="addmeal">
      <button class="close" aria-label="close">\u00D7</button>
      <h3>${t('addm.title')}</h3>
      <div class="am-grid">
        <label class="am-field am-wide"><span>${t('addm.name')}</span><input id="am-name" type="text"></label>
        <label class="am-field"><span>${t('addm.type')}</span><select id="am-type" class="sel">${MEAL_KEYS.map(k=>`<option value="${k}">${MEAL_LABEL[k]}</option>`).join('')}</select></label>
        <label class="am-field"><span>${t('addm.kcal')}</span><input id="am-kcal" type="number" inputmode="numeric"></label>
        <label class="am-field"><span>${t('addm.p')}</span><input id="am-p" type="number" inputmode="numeric"></label>
        <label class="am-field"><span>${t('addm.f')}</span><input id="am-f" type="number" inputmode="numeric"></label>
        <label class="am-field"><span>${t('addm.c')}</span><input id="am-c" type="number" inputmode="numeric"></label>
        <label class="am-field am-wide"><span>${t('addm.ing')}</span><textarea id="am-ing" rows="4"></textarea></label>
        <label class="am-field am-wide"><span>${t('addm.steps')}</span><textarea id="am-steps" rows="3"></textarea></label>
        <label class="am-field am-wide"><span>${t('addm.benefit')}</span><textarea id="am-benefit" rows="2"></textarea></label>
      </div>
      <div class="am-btns"><button class="btn btn-ghost" id="am-cancel">${t('addm.cancel')}</button><button class="btn btn-primary" id="am-save">${t('addm.save')}</button></div>
    </div>`;
  $('#overlay').classList.add('on');document.body.style.overflow='hidden';$('#modal').scrollTop=0;
  $('#modal .close').addEventListener('click',closeModal);
  $('#am-cancel').addEventListener('click',closeModal);
  $('#am-save').addEventListener('click',()=>{
    const name=$('#am-name').value.trim();const kcal=parseInt($('#am-kcal').value,10);
    if(!name||!kcal){if(!name)$('#am-name').classList.add('am-err');if(!kcal)$('#am-kcal').classList.add('am-err');return;}
    const lines=id=>$(id).value.split('\n').map(x=>x.trim()).filter(Boolean);
    const c={id:Date.now(),name:name,meal:$('#am-type').value,kcal:kcal,p:parseInt($('#am-p').value,10)||0,f:parseInt($('#am-f').value,10)||0,c:parseInt($('#am-c').value,10)||0,ingredients:lines('#am-ing'),steps:lines('#am-steps'),benefits:$('#am-benefit').value.trim(),goals:[]};
    CUSTOM.push(c);apiSaveMeal(c);RECIPES.push(makeRecipe(c));reindex();renderGrid();buildPlan(false);closeModal();
  });
}
function deleteCustom(id){
  CUSTOM=CUSTOM.filter(c=>c.id!==id);apiDeleteMeal(id);
  const i=RECIPES.findIndex(r=>r.custom&&r.id===id);if(i>=0)RECIPES.splice(i,1);
  reindex();renderGrid();buildPlan(false);closeModal();
}
(function(){const b=$('#add-meal-btn');if(b)b.addEventListener('click',openAddMeal);})();

// ====================== REMINDERS ======================
function remOn(){try{return localStorage.getItem('sbf-reminders')==='1';}catch(e){return false;}}
function setRem(v){try{localStorage.setItem('sbf-reminders',v?'1':'0');}catch(e){}}
function loggedToday(){const r=HABIT.days[TODAY_KEY];return !!(r&&r.kcal!=null);}
function maybeNotify(){
  if(!remOn()||loggedToday())return;
  try{
    if(typeof Notification!=='undefined'&&Notification.permission==='granted'){
      let last;try{last=localStorage.getItem('sbf-rem-last');}catch(e){}
      if(last!==TODAY_KEY){new Notification(t('rem.notif_title'),{body:t('rem.notif_body')});try{localStorage.setItem('sbf-rem-last',TODAY_KEY);}catch(e){}}
    }
  }catch(e){}
}
function enableReminders(){
  setRem(true);
  try{if(typeof Notification!=='undefined'&&Notification.permission==='default')Notification.requestPermission().then(()=>maybeNotify());else maybeNotify();}catch(e){}
}
function reminderBanner(){
  const host=$('#today-body');if(!host)return;
  if(!remOn()||loggedToday())return;
  const div=document.createElement('div');div.className='rem-banner glass';
  div.innerHTML=`<svg class="i"><use href="#i-spark"/></svg><span>${t('rem.banner')}</span><button class="btn btn-primary" id="rem-lognow">${t('rem.log_now')}</button>`;
  host.insertBefore(div,host.firstChild);
  const b=$('#rem-lognow');if(b)b.addEventListener('click',()=>openDayEditor(TODAY_KEY));
}
const _renderTodayBase=renderToday;
renderToday=function(){_renderTodayBase();reminderBanner();};

