// ====================== ONBOARDING ======================
function onboardDone(){try{return localStorage.getItem('sbf-onboard')==='done';}catch(e){return false;}}
function setOnboardDone(){try{localStorage.setItem('sbf-onboard','done');}catch(e){}}
const OB={step:0,sex:'female',age:30,h:168,w:68,act:1.55,goal:'lose',diet:new Set(),rem:false};
function obTarget(){CALC.sex=OB.sex;CALC.age=OB.age;CALC.h=OB.h;CALC.w=OB.w;CALC.act=OB.act;CALC.goal=OB.goal;return safeTarget();}
function renderOnboard(){
  const host=$('#ob-overlay');if(!host)return;
  let body='';
  if(OB.step===0){
    body=`<div class="ob-step ob-welcome">
      <div class="ob-badge"><svg class="gx"><use href="#gx-flex"/></svg></div>
      <h2>${t('ob.welcome_t')}</h2><p>${t('ob.welcome_p')}</p>
      <div class="ob-actions"><button class="btn btn-primary" data-ob="start">${t('ob.start')}</button><button class="btn btn-ghost" data-ob="skip">${t('ob.skip')}</button></div>
    </div>`;
  } else if(OB.step===1){
    body=`<div class="ob-step">
      <div class="ob-head"><h2>${t('ob.goal_t')}</h2><p>${t('ob.goal_p')}</p></div>
      <div class="ob-form">
        <div class="field"><label>${t('calc.you_are')}</label><div class="seg" id="ob-sex"><button data-v="female" class="${OB.sex==='female'?'on':''}">${t('calc.woman')}</button><button data-v="male" class="${OB.sex==='male'?'on':''}">${t('calc.man')}</button></div></div>
        <div class="numrow">
          <div class="field"><label>${t('calc.age')}</label><div class="num"><button data-obf="age" data-d="-1">&minus;</button><input id="ob-age" type="number" value="${OB.age}"><button data-obf="age" data-d="1">+</button></div></div>
          <div class="field"><label>${t('calc.height')}</label><div class="num"><button data-obf="h" data-d="-1">&minus;</button><input id="ob-h" type="number" value="${OB.h}"><button data-obf="h" data-d="1">+</button></div></div>
          <div class="field"><label>${t('calc.weight')}</label><div class="num"><button data-obf="w" data-d="-1">&minus;</button><input id="ob-w" type="number" value="${OB.w}"><button data-obf="w" data-d="1">+</button></div></div>
        </div>
        <div class="field"><label>${t('calc.activity')}</label><select class="sel" id="ob-act">
          <option value="1.2" ${OB.act==1.2?'selected':''}>${t('calc.act1')}</option><option value="1.375" ${OB.act==1.375?'selected':''}>${t('calc.act2')}</option><option value="1.55" ${OB.act==1.55?'selected':''}>${t('calc.act3')}</option><option value="1.725" ${OB.act==1.725?'selected':''}>${t('calc.act4')}</option><option value="1.9" ${OB.act==1.9?'selected':''}>${t('calc.act5')}</option></select></div>
        <div class="field"><label>${t('calc.goal')}</label><div class="seg" id="ob-goal"><button data-v="lose" class="${OB.goal==='lose'?'on':''}">${t('calc.lose')}</button><button data-v="maintain" class="${OB.goal==='maintain'?'on':''}">${t('calc.maintain')}</button><button data-v="gain" class="${OB.goal==='gain'?'on':''}">${t('calc.build')}</button></div></div>
        <div class="ob-target">${t('calc.target')}: <b id="ob-tnum">${fmt(obTarget())}</b> ${t('calc.kcal')}</div>
      </div>
      <div class="ob-actions"><button class="btn btn-ghost" data-ob="back">${t('ob.back')}</button><button class="btn btn-primary" data-ob="next">${t('ob.next')}</button></div>
    </div>`;
  } else if(OB.step===2){
    body=`<div class="ob-step">
      <div class="ob-head"><h2>${t('ob.diet_t')}</h2><p>${t('ob.diet_p')}</p></div>
      <div class="chips ob-diet">${DIET_DEFS.map(d=>`<button class="chip${OB.diet.has(d.key)?' on':''}" data-obdiet="${d.key}">${dietLabel(d.key)}</button>`).join('')}</div>
      <div class="ob-actions"><button class="btn btn-ghost" data-ob="back">${t('ob.back')}</button><button class="btn btn-primary" data-ob="finish">${t('ob.finish')}</button></div>
    </div>`;
  }
  host.innerHTML=`<div class="ob-card glass">${body}</div>`;
  host.querySelectorAll('[data-ob]').forEach(b=>b.addEventListener('click',()=>obAction(b.dataset.ob)));
  if(OB.step===1){
    host.querySelectorAll('#ob-sex button').forEach(b=>b.addEventListener('click',()=>{OB.sex=b.dataset.v;renderOnboard();}));
    host.querySelectorAll('#ob-goal button').forEach(b=>b.addEventListener('click',()=>{OB.goal=b.dataset.v;renderOnboard();}));
    host.querySelectorAll('[data-obf]').forEach(b=>b.addEventListener('click',()=>{const f=b.dataset.obf;OB[f]=(+$('#ob-'+f).value||0)+(+b.dataset.d);renderOnboard();}));
    ['age','h','w'].forEach(f=>{const el=$('#ob-'+f);if(el)el.addEventListener('input',e=>{OB[f]=+e.target.value||0;$('#ob-tnum').textContent=fmt(obTarget());});});
    const act=$('#ob-act');if(act)act.addEventListener('change',e=>{OB.act=+e.target.value;$('#ob-tnum').textContent=fmt(obTarget());});
  }
  if(OB.step===2){
    host.querySelectorAll('[data-obdiet]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.obdiet;OB.diet.has(k)?OB.diet.delete(k):OB.diet.add(k);b.classList.toggle('on');}));
    const rt=$('#ob-remtoggle');if(rt)rt.addEventListener('click',()=>{OB.rem=!OB.rem;rt.classList.toggle('on',OB.rem);});
  }
}

// ====================== APP INIT ======================
// Тільки сервер. Ніякого localStorage для даних.

async function initApp(){
  const serverData = await apiLoadUserData();

  if (!serverData) {
    console.warn('[initApp] server unavailable');
    return;
  }

  if (serverData.settings) {
    HABIT.waterGoal = serverData.settings.water_goal  || 8;
    HABIT.target    = serverData.settings.kcal_target || 1600;
  }

  if (serverData.days) {
    HABIT.days = serverData.days;
  }

  if (serverData.meals) {
    CUSTOM = serverData.meals;
    RECIPES.splice(0, RECIPES.length, ...RECIPES.filter(r => !r.custom));
    mountCustom();
  }

  renderToday();
  renderGrid();
}

initApp();
function obAction(a){
  if(a==='skip'){finishOnboard(false);return;}
  if(a==='start'){OB.step=1;renderOnboard();return;}
  if(a==='back'){OB.step=Math.max(0,OB.step-1);renderOnboard();return;}
  if(a==='next'){OB.step=2;renderOnboard();return;}
  if(a==='finish'){finishOnboard(true);return;}
}
function finishOnboard(apply){
  if(apply){
    TARGET=obTarget();HABIT.target=TARGET;saveHabit();
    const tr=$('#t-range');if(tr){tr.value=Math.min(3000,Math.max(1100,TARGET));$('#t-val').textContent=fmt(TARGET);}
    renderCalc();
    OB.diet.forEach(k=>{fDiet.add(k);planDiet.add(k);});
    buildDietChips();buildGenDietChips();
    if(OB.rem)enableReminders();
    buildPlan(false);renderGrid();
  }
  setOnboardDone();
  const host=$('#ob-overlay');if(host){host.classList.remove('on');host.innerHTML='';}
  document.body.style.overflow='';
  renderToday();
}
function startOnboarding(){
  if(onboardDone())return;
  let host=$('#ob-overlay');
  if(!host){host=document.createElement('div');host.id='ob-overlay';host.className='ob-overlay';document.body.appendChild(host);}
  host.classList.add('on');document.body.style.overflow='hidden';OB.step=0;renderOnboard();
}

// ====================== FINAL INIT (after custom + features) ======================
renderGrid();buildPlan(false);renderToday();
(function(){const sm=$('#stat-meals'); if(sm)sm.textContent=RECIPES.length;})();
startOnboarding();
maybeNotify();
setInterval(maybeNotify,60*60*1000);

